// Normalize all extracted PDF text
const combined = [];
for (const item of items) {
  const docs = Array.isArray(item.json) ? item.json : [item.json];
  for (const d of docs) {
    combined.push({
      json: {
        sourceName: d.fileName || d.sourceName || 'Unknown Document',
        sourceType: d.fileName?.match(/BRD|FRD|LLD|HLD/)?.[0] || 'Document',
        text: d.text || '',
        timestamp: new Date().toISOString()
      }
    });
  }
}
return combined;

// Normalize Transcript Text
let combinedText = '';
for (const item of items) {
  let text = '';
  if (item.binary && item.binary.data) {
    const dataBuffer = Buffer.from(item.binary.data.data || item.binary.data, 'base64');
    text = dataBuffer.toString('utf8');
  } else if (item.json && item.json.data) {
    text = item.json.data.toString();
  } else if (item.json && item.json.text) {
    text = item.json.text.toString();
  }
  combinedText += '\n\n' + text.trim();
}
combinedText = combinedText.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').replace(/\s{2,}/g, ' ').trim();
return [{ json: { normalized_transcript: combinedText, summary: `Normalized transcript text.` } }];

// Merge normalized docs and transcript into one large text blob
let allTexts = [];

for (const item of items) {
  const src =
    item.json.sourceName ||
    item.json.summary ||
    item.json.sourceType ||
    "Unknown Source";

  const txt =
    item.json.text ||
    item.json.normalized_transcript ||
    item.json.content ||
    "";

  if (txt.trim()) {
    allTexts.push(`Source: ${src}\n${txt}`);
  }
}

// Return merged context safely
return [
  {
    json: {
      mergedContext: allTexts.join("\n---\n"),
      contextCount: allTexts.length,
    },
  },
];
